const express = require('express');
const { createYoga, createSchema } = require('graphql-yoga');
const { GraphQLError } = require('graphql');
const { PrismaClient } = require('@prisma/client');

const prisma = new PrismaClient();
const app = express();

const typeDefs = `
  type KubernetesCluster @key(fields: "id") {
    id: ID!
    clusterName: String!
    apiServerEndpoint: String!
    kubeconfigSecretArn: String!
    nodeCount: Int!
  }

  type Query {
    ping: String
  }
`;

const resolvers = {
  KubernetesCluster: {
    __resolveReference: async (reference, context) => {
      if (!context.auth || !context.auth.organizationId) {
        throw new GraphQLError('Authentication context missing', {
          extensions: { code: 'UNAUTHENTICATED' }
        });
      }

      const cluster = await prisma.kubernetesCluster.findFirst({
        where: {
          id: reference.id,
          organizationId: context.auth.organizationId
        }
      });

      if (!cluster) {
        throw new GraphQLError('Cluster not found or permission denied', {
          extensions: { code: 'FORBIDDEN' }
        });
      }

      return cluster;
    }
  }
};

const yoga = createYoga({
  schema: createSchema({ typeDefs, resolvers }),
  graphqlEndpoint: '/subgraph/cloud',
  context: async ({ req }) => {
    return {
      auth: req.user
    };
  }
});

app.use('/subgraph/cloud', yoga);
app.listen(5050);
